<template><div class="settings-tiles"><button v-for="item in tabs" :key="item.id" :class="{selected:tab===item.id}" @click="tab=item.id"><strong>{{item.title}}</strong><small>{{item.description}}</small></button></div><div class="grid-two"><div><PlatformConfiguration v-if="tab==='configuration'"/><UsersSettings v-else-if="tab==='users'"/><ServiceChecksSettings v-else-if="tab==='services'"/><BackupSettings v-else-if="tab==='backups'"/><UpgradeSettings v-else-if="tab==='upgrade'"/></div><PanelCard title="平台健康状态"><ResourceState :error="error" @retry="refresh"/><dl v-if="data" class="facts"><dt>平台版本</dt><dd>{{data.version}}</dd><dt>源码版本</dt><dd><code>{{data.sourceCommit?.slice(0,12)}}</code></dd><dt>Spring Boot</dt><dd><StateBadge :status="data.platform==='UP'?'healthy':'UNKNOWN'"/></dd><dt>H2 数据库</dt><dd><StateBadge :status="data.database==='UP'?'healthy':'UNKNOWN'"/></dd><dt>/mnt/disk01 挂载</dt><dd><StateBadge :status="data.mounted?'healthy':'failed'"/></dd><dt>Docker 连接</dt><dd><StateBadge :status="dockerConnected?'healthy':'UNKNOWN'"/></dd><dt>数据版本</dt><dd>{{data.schemaVersion}}</dd><dt>数据库目录</dt><dd><code>{{data.dataDirectory}}</code></dd></dl><p class="muted" style="margin-top:22px">平台自身以本地 Java 进程运行；Docker、Runtime OS 和业务数据库不构成平台启动依赖。</p><RouterLink to="/audit">查看操作审计 →</RouterLink></PanelCard></div></template>
<script setup>
import {ref,computed} from 'vue';import {useCluster} from '../../stores/cluster';import {platformApi} from '../../api/platform';import {useResource} from '../../composables/useResource';import PanelCard from '../../components/ui/PanelCard.vue';import StateBadge from '../../components/ui/StateBadge.vue';import ResourceState from '../../components/ui/ResourceState.vue';import PlatformConfiguration from '../../components/settings/PlatformConfiguration.vue';import UsersSettings from '../../components/settings/UsersSettings.vue';import ServiceChecksSettings from '../../components/settings/ServiceChecksSettings.vue';import BackupSettings from '../../components/settings/BackupSettings.vue';import UpgradeSettings from '../../components/settings/UpgradeSettings.vue';const {inventory}=useCluster(),dockerConnected=computed(()=>inventory.value.some(node=>!!node.data)),tab=ref('backups'),{data,error,refresh}=useResource(platformApi.health,{interval:15000}),tabs=[{id:'configuration',title:'平台配置',description:'基础配置与应用入口'},{id:'users',title:'用户与权限',description:'账号管理与角色权限'},{id:'services',title:'服务监控',description:'健康探针与多地址集群'},{id:'backups',title:'H2 备份恢复',description:'一致性备份与恢复管理'},{id:'upgrade',title:'平台升级',description:'离线升级与失败恢复'}];
</script>
